macro_rules! Spacing {
    () => {
        # [doc = " Indicates whether a token can join with the following token to form a"] # [doc = " compound token. Used for conversions to `proc_macro::Spacing`. Also used to"] # [doc = " guide pretty-printing, which is where the `JointHidden` value (which isn't"] # [doc = " part of `proc_macro::Spacing`) comes in useful."] # [derive (Debug , Clone , Copy , PartialEq , Eq , Hash)] pub enum Spacing { # [doc = " The token cannot join with the following token to form a compound"] # [doc = " token."] # [doc = ""] # [doc = " In token streams parsed from source code, the compiler will use `Alone`"] # [doc = " for any token immediately followed by whitespace, a non-doc comment, or"] # [doc = " EOF."] # [doc = ""] # [doc = " When constructing token streams within the compiler, use this for each"] # [doc = " token that (a) should be pretty-printed with a space after it, or (b)"] # [doc = " is the last token in the stream. (In the latter case the choice of"] # [doc = " spacing doesn't matter because it is never used for the last token. We"] # [doc = " arbitrarily use `Alone`.)"] # [doc = ""] # [doc = " Converts to `proc_macro::Spacing::Alone`, and"] # [doc = " `proc_macro::Spacing::Alone` converts back to this."] Alone , # [doc = " The token can join with the following token to form a compound token."] # [doc = ""] # [doc = " In token streams parsed from source code, the compiler will use `Joint`"] # [doc = " for any token immediately followed by punctuation (as determined by"] # [doc = " `Token::is_punct`)."] # [doc = ""] # [doc = " When constructing token streams within the compiler, use this for each"] # [doc = " token that (a) should be pretty-printed without a space after it, and"] # [doc = " (b) is followed by a punctuation token."] # [doc = ""] # [doc = " Converts to `proc_macro::Spacing::Joint`, and"] # [doc = " `proc_macro::Spacing::Joint` converts back to this."] Joint , # [doc = " The token can join with the following token to form a compound token,"] # [doc = " but this will not be visible at the proc macro level. (This is what the"] # [doc = " `Hidden` means; see below.)"] # [doc = ""] # [doc = " In token streams parsed from source code, the compiler will use"] # [doc = " `JointHidden` for any token immediately followed by anything not"] # [doc = " covered by the `Alone` and `Joint` cases: an identifier, lifetime,"] # [doc = " literal, delimiter, doc comment."] # [doc = ""] # [doc = " When constructing token streams, use this for each token that (a)"] # [doc = " should be pretty-printed without a space after it, and (b) is followed"] # [doc = " by a non-punctuation token."] # [doc = ""] # [doc = " Converts to `proc_macro::Spacing::Alone`, but"] # [doc = " `proc_macro::Spacing::Alone` converts back to `token::Spacing::Alone`."] # [doc = " Because of that, pretty-printing of `TokenStream`s produced by proc"] # [doc = " macros is unavoidably uglier (with more whitespace between tokens) than"] # [doc = " pretty-printing of `TokenStream`'s produced by other means (i.e. parsed"] # [doc = " source code, internally constructed token streams, and token streams"] # [doc = " produced by declarative macros)."] JointHidden , }
    };
}

Spacing!();